require_once __DIR__.'/../includes/auth.php';require_login();require_premium();if(!in_array(user_grade_number(),[10,11],true)){redirect('student/dashboard.php');}$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$type=($_GET['type']??'')==='answers'?'answers':'paper';$p=$id?query_one('SELECT * FROM ol_papers WHERE id=? AND status=1','i',[$id]):null;$path=$p?($type==='answers'?$p['answer_sheet_path']:$p['paper_file_path']):null;$root=realpath(__DIR__.'/../uploads/ol-papers');$file=$path?realpath(__DIR__.'/../'.ltrim($path,'/')):false;if(!$p||!$file||!$root||strncmp($file,$root,strlen($root))!==0||!is_file($file)||strtolower(pathinfo($file,PATHINFO_EXTENSION))!=='pdf'){http_response_code(404);exit('File not found');}header('Content-Type: application/pdf');header('Content-Length: '.filesize($file));if(isset($_GET['download']))header('Content-Disposition: attachment; filename="ol-paper-'.$p['year'].'-'.$type.'.pdf"');else header('Content-Disposition: inline');readfile($file);
